/* Neo Brutalism Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Neo Brutalism Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 255 255 255;
    --foreground: 0 0 0;
    --card: 255 255 255;
    --card-foreground: 0 0 0;
    --popover: 255 255 255;
    --popover-foreground: 0 0 0;
    --primary: 255 53 52;
    --primary-foreground: 255 255 255;
    --secondary: 254 255 85;
    --secondary-foreground: 0 0 0;
    --muted: 242 242 242;
    --muted-foreground: 51 51 51;
    --accent: 0 101 253;
    --accent-foreground: 255 255 255;
    --destructive: 0 0 0;
    --destructive-foreground: 255 255 255;
    --border: 0 0 0;
    --input: 0 0 0;
    --ring: 255 53 52;
    --chart-1: 255 53 52;
    --chart-2: 254 255 85;
    --chart-3: 0 101 253;
    --chart-4: 0 203 0;
    --chart-5: 202 3 202;
    --radius: 0px;
    --sidebar: 242 242 242;
    --sidebar-foreground: 0 0 0;
    --sidebar-primary: 255 53 52;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 0 101 253;
    --sidebar-accent-foreground: 255 255 255;
    --sidebar-border: 0 0 0;
    --sidebar-ring: 255 53 52;
    --font-sans: DM Sans, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Space Mono, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 1;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 4px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
    --shadow-xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
    --shadow-sm:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
    --shadow: 4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
    --shadow-md:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 2px 4px -1px hsl(0 0% 0% / 1);
    --shadow-lg:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 4px 6px -1px hsl(0 0% 0% / 1);
    --shadow-xl:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 8px 10px -1px hsl(0 0% 0% / 1);
    --shadow-2xl: 4px 4px 0px 0px hsl(0 0% 0% / 2.5);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 0 0 0;
    --foreground: 255 255 255;
    --card: 51 51 51;
    --card-foreground: 255 255 255;
    --popover: 51 51 51;
    --popover-foreground: 255 255 255;
    --primary: 255 99 100;
    --primary-foreground: 0 0 0;
    --secondary: 254 255 77;
    --secondary-foreground: 0 0 0;
    --muted: 51 51 51;
    --muted-foreground: 206 206 206;
    --accent: 55 155 255;
    --accent-foreground: 0 0 0;
    --destructive: 255 255 255;
    --destructive-foreground: 0 0 0;
    --border: 255 255 255;
    --input: 255 255 255;
    --ring: 255 99 100;
    --chart-1: 255 99 100;
    --chart-2: 254 255 77;
    --chart-3: 55 155 255;
    --chart-4: 47 205 48;
    --chart-5: 204 46 204;
    --radius: 0px;
    --sidebar: 0 0 0;
    --sidebar-foreground: 255 255 255;
    --sidebar-primary: 255 99 100;
    --sidebar-primary-foreground: 0 0 0;
    --sidebar-accent: 55 155 255;
    --sidebar-accent-foreground: 0 0 0;
    --sidebar-border: 255 255 255;
    --sidebar-ring: 255 99 100;
    --font-sans: DM Sans, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Space Mono, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 1;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 4px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
    --shadow-xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
    --shadow-sm:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
    --shadow: 4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
    --shadow-md:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 2px 4px -1px hsl(0 0% 0% / 1);
    --shadow-lg:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 4px 6px -1px hsl(0 0% 0% / 1);
    --shadow-xl:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 8px 10px -1px hsl(0 0% 0% / 1);
    --shadow-2xl: 4px 4px 0px 0px hsl(0 0% 0% / 2.5);
  }

}
